const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
let lineCount = 0;

rl.on('line', (line) => {
    lines.push(line);
    lineCount++;
    if (lineCount === 3) {
        rl.close();
        processInput(lines);
    }
